UPDATE companies SET description='Rex Plastics operates from Vancouver, Washington, where it has been manufacturing plastic injection molded parts since 1971. The company is a second-generation, family-owned and operated contract manufacturer that began with a focus on domestic mold building and material sourcing.

The shop provides full-service injection molding, including mold design and construction backed by a lifetime guarantee, design-for-manufacturing assistance, prototyping via 3D printing, first-article inspection, and production runs from short-run to high-volume. Secondary operations encompass pad printing, hydrographics, assembly, packaging, and light distribution. The facility produces components such as the 200,000 squeegees it molds annually for Artscape.

Rex Plastics serves OEMs and startups across sports equipment, electronics, medical, communications, and consumer products. Its client roster includes International Electronics, Boyd Coffee, Artscape, Stormwater Management, Pacific Coast Marine, and Trident Design, among others. The company reports a 98 percent OEM retention rate over the past decade.

The firm differentiates itself by insisting on U.S.-built molds and domestically sourced raw materials whenever possible, offering a lifetime mold guarantee, and providing end-to-end service from concept through retail-ready packaging. Founders emphasize a commitment to positive community impact and long-term customer relationships.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Plastic injection molding", "Injection mold building (with lifetime guarantee)", "Design assistance / reverse engineering", "Prototyping (including 3D printing)", "First article inspection", "Production molding (short-run and high-volume)", "Pad printing", "Hydrographics", "Assembly", "Packaging", "Light distribution", "3D printing services", "Plastic product design", "Design-for-manufacturing (DFM) assistance"], "industries": ["Sports equipment", "Electronics", "Medical", "Communications", "Consumer products"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Lifetime mold guarantee on all injection molds", "Molds built and materials sourced domestically in the USA", "98% OEM client retention over ten years", "Full-service from design through packaging and distribution", "Design-for-manufacturing (DFM) assistance and prototyping"], "facts_used": ["Founded 1971 -> /", "Family-owned, second generation -> db description", "Location Vancouver, Washington -> db hq_city, hq_state_label", "Plastic injection molding contract manufacturer -> db description", "Lifetime mold guarantee -> / and /services", "Domestic mold building and material sourcing -> db description", "98% OEM client retention over past decade -> / and /services", "Services: injection molding, mold making, design/prototyping, secondary operations (pad printing, hydrographics, assembly, packaging, light distribution) -> / and /services", "Industries: sports equipment, electronics, medical, communications, consumer products -> /", "Customer examples: International Electronics, Boyd Coffee, Artscape, Stormwater Management, Pacific Coast Marine, Trident Design -> /", "Annual volume example: 200,000 squeegees for Artscape -> /", "Full-service from conception to completion -> db description and /", "Design-for-manufacturing assistance -> /services", "3D printing and plastic product design -> / and capabilities list", "Short-run and large production runs -> capabilities list"], "company_type": "Contract manufacturer / job shop", "makes_products": "yes", "type_evidence": "Rex Plastics is a second generation, family-owned and operated full-service plastic injection molding contract manufacturer.", "founded_year": "1971", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='rex-plastics-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Ricardo Food Group Inc. operates from New York City and was founded in 1991 by Ricardo Cordero.

The company functions as an advisory firm specializing in sourcing co-packing, private label, and contract manufacturing partnerships for the food, bakery, beverage, and plant-based sectors. It maintains an active portfolio of more than 600 U.S.-based manufacturing facilities and leverages 35 years of production expertise to match clients with suitable partners. Beyond sourcing, RFG provides advisory services for acquisitions, debt restructuring, management buyouts, and capital investment strategies.

Clients range from emerging brands seeking to expand capacity to established companies pursuing economies of scale. The firm serves the food, bakery, beverage, and plant-based industries, assisting with product line extensions, brand rejuvenation, and cost control.

RFG emphasizes its deep relationships with contract manufacturers as a core differentiator, stating that its network often yields cost-saving or value-added benefits clients might not identify independently. The firm positions itself as a bridge between brands and production resources, aiming to reduce the risk and complexity of sourcing manufacturing partners.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Consulting", "Acquisitions advisory", "Debt restructuring", "Management buyouts", "Co-packing sourcing", "Private label sourcing", "Contract manufacturing sourcing", "Plant-based product development", "Bulk foods sourcing"], "industries": ["Food", "Bakery", "Beverage", "Plant-based foods"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Active portfolio of 600+ U.S. contract manufacturing facilities", "35 years of manufacturing and production expertise", "Sourcing for co-packing, private label, and contract manufacturing", "Advisory services for acquisitions, debt restructuring, and management buyouts"], "facts_used": ["Founded 1991 -> db", "Headquarters New York, NY -> db", "Founder Ricardo Cordero -> / (home page quote) and /about", "Active portfolio of 600+ U.S. facilities -> / and /about", "35 years of manufacturing expertise -> / and /about", "Services: consulting, acquisitions, debt restructuring, management buyouts -> db and /about", "Industries: food, bakery, beverage, plant-based -> db and /about", "Co-packing, private label, contract manufacturing sourcing -> / and /about"], "company_type": "Other", "makes_products": "no", "type_evidence": "Ricardo Food Group is an advisory firm made up of Manufacturing and Production Expert Consultants in the food, bakery, plant base and beverage industry.", "founded_year": "1991", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug