UPDATE companies SET description='Rohrer Manufacturing was founded in 1997 in Prineville, Oregon, as a family-owned business producing the Man Saver pneumatic post driver. The company has remained in Prineville since its inception, manufacturing every unit domestically.

The company designs and builds the patented Man Saver pneumatic post driver, a lightweight, portable tool that drives posts without hydraulics. Its product line includes the 91-R driver for posts up to 2-3/8″ OD, along with a range of accessories: round and T-post adapters, high-pressure upgrade kits, inline oilers, and lubrication oil. All assembly and fulfillment occur at the Prineville facility, with orders shipped primarily via UPS.

Rohrer’s drivers are used on ranches, vineyards, and highway projects, as well as by residential and agricultural fencing contractors and DIY customers. The tool is marketed for one-person operation, enabling a single operator to install fence lines that would otherwise require a crew.

The business was built around the idea that a pneumatic driver could replace manual post driving, cutting labor costs, fatigue, and injury risk. The patented mechanism delivers consistent post placement, and the company emphasizes American-made construction and direct-to-customer shipping as core differentiators.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Pneumatic post driver manufacturing", "Post driver accessory production", "Patented pneumatic driver design", "Order fulfillment and shipping via UPS"], "industries": ["Ranches", "Vineyards", "Highway work", "Residential fencing", "Agricultural fencing", "Contractors", "DIY"], "materials": [], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Patented pneumatic Man-Saver driver design", "One-person operation eliminates need for a crew", "Lightweight, portable, no hydraulics required", "American-made in Prineville, Oregon", "Direct shipping via UPS"], "facts_used": ["Family-owned, founded 1997, Prineville, Oregon -> db", "Manufactures Man Saver pneumatic post drivers -> /", "Patented pneumatic driver design -> /", "Accessories include adapters, lube oil, kits -> /", "Serves ranches, vineyards, highway work, residential and agricultural fencing, contractors, DIYers -> /", "Uses UPS for shipping -> /", "American-made -> /", "One-person operation -> /", "Lightweight and portable -> /", "No hydraulics needed -> /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "manufacture every Man Saver Post Driver right here in Prineville, Oregon, USA", "founded_year": "1997", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='rohrer-manufacturing' AND approved AND profile IS NULL;
UPDATE companies SET description='Roltgen''s Woodworks operates from Piedmont, South Dakota, where sole proprietor Jeff Roltgen designs, drafts, and builds custom furnishings. Roltgen brought over a decade of CAD drafting experience to the venture and adopted digital fabrication methods in 2012, blending traditional hand-tool techniques with modern efficiency.

The shop produces one-of-a-kind furniture pieces and a range of cabinetry, including bath vanities, built-ins, and complete kitchens. Services extend to renovation and remodeling, exterior design, and office furniture. Roltgen handles each project personally, from on-site consultation through final delivery, using a mix of hand tools and digital equipment.

Clients include homeowners seeking heirloom-quality furniture, as well as commercial customers needing custom office furnishings or remodel work.

Roltgen emphasizes a direct designer-builder relationship, giving customers a hand in the design process and guaranteeing attention to detail that mass-produced items cannot match. The business was built on the premise that personal craftsmanship and modern tools together create genuine, lasting pieces.', certifications=ARRAY[]::text[], profile='{"capabilities": ["Custom furniture design and construction", "CAD drafting and design", "Digital fabrication", "Traditional woodworking", "Cabinetry (bath vanities, built-ins, kitchens)", "Renovation and remodeling", "Exterior design", "Office furniture design and build", "On-site consultation", "Hand-tool finishing"], "industries": ["Custom furniture", "Cabinetry", "Renovation and remodeling", "Office furniture", "Exterior design", "Woodworking"], "materials": ["Wood"], "equipment": [], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Direct designer-builder relationship with on-site consultation", "Blends traditional hand-tool techniques with digital fabrication (since 2012)", "Sole proprietor handles design, drafting, construction, and delivery", "Custom furniture and cabinetry from bath vanities to complete kitchens"], "facts_used": ["Location: Piedmont, South Dakota -> db", "Sole proprietor: Jeff Roltgen -> page /", "CAD drafting experience 10+ years, digital fabrication since 2012 -> page /", "Services: custom furniture, cabinetry (bath vanities, built-ins, kitchens), renovation, remodeling, exterior design, office furniture -> page /", "Featured in FDMC magazine \"Best Practices in Woodworking Technology & Business\" -> page /", "Direct designer-builder relationship, on-site consultation -> page /", "Blends traditional methodology with modern efficiencies -> page /"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Jeff Roltgen is the sole proprietor, designing, drafting, constructing and delivering one of a kind custom furnishings.", "founded_year": "", "employee_count": "1",